<?php
declare(strict_types=1);
use App\Core\Auth;
use App\Core\Totp;
require dirname(__DIR__) . '/TestEnvironment.php';
$env = velvet_test_environment('admin-security'); $checks = 0;
$assert = static function (bool $ok, string $why) use (&$checks): void { $checks++; if (!$ok) throw new RuntimeException($why); };
$reject = static function (callable $fn, string $why) use ($assert): void { $rejected = false; try { $fn(); } catch (Throwable) { $rejected = true; } $assert($rejected, $why); };
try {
    $store = $env['store']; $auth = new Auth($store); $secret = Totp::encode('12345678901234567890');
    foreach ([0=>'755224',1=>'287082',2=>'359152',3=>'969429',4=>'338314',5=>'254676',6=>'287922',7=>'162583',8=>'399871',9=>'520489'] as $counter=>$expected) $assert(Totp::code($secret, $counter) === $expected, 'RFC4226 vector failed.');
    foreach ([59=>'94287082',1111111109=>'07081804',1111111111=>'14050471',1234567890=>'89005924',2000000000=>'69279037',20000000000=>'65353130'] as $at=>$expected) $assert(Totp::code($secret, intdiv($at,30), 8) === $expected, 'RFC6238 SHA1 vector failed.');
    $assert(Totp::match($secret, Totp::code($secret,100),3000)===100,'Valid time code refused.');
    $assert(Totp::match($secret, Totp::code($secret,100),3000,100)===null,'Replayed time code accepted.');
    $assert(Totp::match($secret, Totp::code($secret,100),3030,100)===null,'Replayed time code accepted after the clock window changed.');
    $assert(Totp::match($secret, Totp::code($secret,101),3030,100)===101,'A new code after clock rollover was confused with a replay.');
    $assert(Totp::match($secret, Totp::code($secret,98),3000)===null,'Old time code accepted.');
    $assert(Totp::match($secret, '1234567',3000)===null,'Malformed code accepted.');
    $id=(string)$store->createAdmin('Security Owner','security-owner@example.test','OwnerSecurity12!');
    $assert($auth->attempt('security-owner@example.test','OwnerSecurity12!'),'Password sign-in failed.');
    $assert($auth->check(),'Saved session failed.'); $auth->requireRecentOwner();
    $assert(!isset($auth->user()['token']) && !isset($auth->user()['stamp']),'Session secrets exposed in public user.');
    $first=$_SESSION['admin'];
    $_SESSION['admin']['authenticated_at']=time()-901; $reject(fn()=>$auth->requireRecentOwner(),'Expired privileged auth accepted.');
    $assert(!$auth->reauthenticate('wrong'),'Wrong confirmation accepted.');
    $assert($auth->reauthenticate('OwnerSecurity12!'),'Correct confirmation refused.');
    $auth->requireRecentOwner();
    $codes=$auth->security()->enable($id,$secret,Totp::code($secret,intdiv(time(),30)),fn()=>$auth->requireRecentOwner());
    $assert(count($codes)===10 && count(array_unique($codes))===10,'Recovery codes not independent.');
    $saved=$store->adminSecurityState();
    $assert(!str_contains(json_encode($saved),$secret),'Plain TOTP secret persisted.');
    foreach($codes as $code)$assert(!str_contains(json_encode($saved),$code),'Plain recovery code persisted.');
    $assert(!$auth->check(),'Factor enable left earlier session authorized.');
    $assert(!$auth->attempt('security-owner@example.test','OwnerSecurity12!') && $auth->pending() && !$auth->check(),'Password bypassed second factor.');
    $assert(!$auth->completeChallenge('wrong'),'Invalid second factor accepted.');
    $assert($auth->completeChallenge($codes[0]) && $auth->check(),'Recovery challenge failed.');
    $assert(!$auth->security()->consumeFactor($id,$codes[0]),'Consumed recovery code replayed.');
    $assert($auth->security()->overview($id)['recovery_count']===9,'Recovery code was not consumed.');
    $new=$_SESSION['admin']; $_SESSION['admin']=$first; $assert(!$auth->check(),'Earlier pre-enrollment session remained valid.'); $_SESSION['admin']=$new;
    $auth->requireRecentOwner();
    $assert($auth->reauthenticate('OwnerSecurity12!',$codes[1]),'Password plus second factor confirmation failed.');
    $oldUa=$_SERVER['HTTP_USER_AGENT']; $_SERVER['HTTP_USER_AGENT']='changed client'; $assert(!$auth->check(),'Changed client session accepted.'); $_SERVER['HTTP_USER_AGENT']=$oldUa; $_SESSION['admin']=$new;
    $assert($auth->check(),'Original session unexpectedly changed.');
    $data=$store->rawFileData(); $data['admins'][$id]['role']='editor'; $store->replaceFileData($data);
    $assert(($auth->user()['role']??null)==='editor','Current saved role not refreshed.'); $reject(fn()=>$auth->requireRecentOwner(),'Demoted owner privileged.');
    $data['admins'][$id]['role']='owner'; $data['admins'][$id]['is_active']=0; $store->replaceFileData($data); $assert(!$auth->check(),'Disabled owner session survived.');
    $data['admins'][$id]['is_active']=1; $store->replaceFileData($data); $_SESSION['admin']=$new;
    $data['admins'][$id]['password_hash']=password_hash('ChangedPassword12!',PASSWORD_DEFAULT); $store->replaceFileData($data); $assert(!$auth->check(),'Changed password retained session.');
    for($i=0;$i<8;$i++)$assert($auth->security()->allowAttempt('rate-only','test',10000),'Early attempt unexpectedly limited.');
    $assert(!$auth->security()->allowAttempt('rate-only','test',10000),'Ninth account attempt accepted.');
    $assert($auth->security()->allowAttempt('rate-only','test',10901),'Expired limiter remained locked.');
    $before=file_get_contents($env['dataPath']);
    $reject(fn()=>$store->mutateAdminSecurity(static function(array &$state):void{$state['admins']=[];throw new RuntimeException('rollback');}),'Mutation exception escaped rollback.');
    $assert(file_get_contents($env['dataPath'])===$before,'Security exception partially saved.');
    $state=$store->adminSecurityState(); $assert(count($state['events'])>0,'Security events not durable.');
    $state['schema']=99; $store->setSetting('_private_admin_security_v1',$state); $reject(fn()=>$auth->attempt('security-owner@example.test','ChangedPassword12!'),'Malformed security state silently reset.');
    echo "Administrator security source passed ($checks checks).\n";
} finally { velvet_test_cleanup($env); }
